descriptor.controllerScript:
let $scope;
let settings;
let prevFilterValue;
let utils;


self.actionSources = function() {
    return {
        'rowClick': {
            name: 'widget-action.row-click',
            multiple: false
        },
        'dateSelected': {
            name: 'date-selected',
            multiple: false
        },
        'changedRadioButton': {
            name: 'changed-radio-button',
            multiple: false
        },
        'elementClick': {
            name: 'widget-action.element-click',
            multiple: true
        }
    };
}

self.onInit = function() {
    $scope = self.ctx.$scope;
    $scope.ctx = self.ctx;
    $scope.jwt = self.getJwtToken();
    $scope.jwtRefresh = self.getRefreshToken();
    $scope.inited = false;

    settings = JSON.parse(JSON.stringify($scope.ctx
        .settings)) || {};
    utils = self.ctx.$scope.$injector.get(self.ctx
        .servicesMap.get('utils'));

    let widgetService = self.ctx.entityService.widgetService;
    let resourceURL = '';

    if(widgetService.widgetsInfoInMemoryCache) {
        let widgetInfo = widgetService.widgetsInfoInMemoryCache.get(self.ctx.widget.typeFullFqn)
        if(widgetInfo && widgetInfo.resources.length) {
            resourceURL = widgetInfo.resources[0].url
        }
    }

    $scope.resourceURL = resourceURL;
    $scope.getJwtToken = self.getJwtToken;
    $scope.ctx.getJwtToken = self.getJwtToken;

    $scope.getRefreshToken = self.getRefreshToken;
    $scope.ctx.getRefreshToken = self.getRefreshToken;

    $scope.onDataChannleInit = self.onDataChannleInit;
    $scope.ctx.onDataChannleInit = self
        .onDataChannleInit;

    self.ctx.jwt = $scope.jwt;
    if (!settings.viewUrl || !settings.view) {
        $scope.inited = false;
    } else {
        $scope.inited = true;
    }

    if (settings.widgetTitle && settings.widgetTitle.length) {
        let titlePattern = utils.customTranslation(settings.widgetTitle, settings.widgetTitle);

        let newTitle;
        if(self.ctx.datasources.length !== 1) {
            newTitle = titlePattern.replace(/\${.*?}/g, "");
        } else {
            let datasource = self.ctx.datasources[0];
            newTitle = utils.createLabelFromDatasource(datasource, titlePattern);
        }

        if (self.ctx.widgeTitle !== newTitle) {
            self.ctx.widgetTitle = newTitle;
            self.ctx.updateWidgetParams();
        }
    }

    self.ctx.$scope.onClick = function(e) {
        if ((e && e.target && e.target.className
                .includes('mat-menu-trigger')) ||
            (e && e.target && e.target.className
                .includes('mat-button-wrapper'))
        ) {
            return;
        }

        let descriptors = self.ctx.$scope.ctx
            .actionsApi.getActionDescriptors(
                'elementClick');
        let actionEvent;
        if (descriptors.length) {
            actionEvent = descriptors[0];

            setTimeout(() => {
                self.ctx.$scope.ctx
                    .actionsApi
                    .handleWidgetAction(
                        null,
                        actionEvent);
            }, 0);
        }

    }
}

self.onDataUpdated = function() {

    let newFilters = readFilterValues();

    if (prevFilterValue === newFilters) {
        return;
    }

    $scope.filterValue = newFilters;
    prevFilterValue = $scope.filterValue;
}

self.onDestroy = function() {
}

self.onEditModeChanged = function(e) {
}

self.onResize = function() {
    if ($scope.subscriptionService) {
        $scope.subscriptionService.emit('parentResize',
            'tb_dashboard', 'onResizeEvent');
    }
}

self.onDataChannleInit = function(subscriptionService) {
    $scope.subscriptionService = subscriptionService;
}

function readFilterValues() {
    if (self.ctx && self.ctx.defaultSubscription && self.ctx
        .defaultSubscription.data && self.ctx
        .defaultSubscription.data.length > 0) {
        let filterValues = [];
        for (let i = 0; i < self.ctx.defaultSubscription
            .data.length; i++) {
            let value = getDescendantProp(self.ctx
                .defaultSubscription.data[i], 'data.0.1'
                );
            if (value && value !== 'Unresolved') {
                filterValues.push(value);
            }
        }
        let fitlerObject = {};
        fitlerObject[settings.filterName] = filterValues;
        return fitlerObject;
    } else {
        usePostMessage = false;
        return null;
    }
}

function getDescendantProp(obj, path) {
    return path.split('.').reduce((acc, part) => acc && acc[
        part], obj)
}

self.getRefreshToken = function() {
    let jwtToken = localStorage.getItem(
    'refresh_token');
    if (jwtToken) {
        jwtToken = jwtToken.replaceAll('"', "");
        return jwtToken;
    }

    return 'unknwown';
}

self.getJwtToken = function() {
    let jwtToken = localStorage.getItem('jwt_token');
    if (jwtToken) {
        jwtToken = jwtToken.replaceAll('"', "");
        return jwtToken;
    }

    return 'unknwown';
}

self.useCustomDatasources = function() {
    return false;
};

self.typeParameters = function() {
    return {
        maxDatasources: 1,
        maxDataKeys: 1,
        singleEntity: false,
        useCustomDatasources: true
    };
};

